// The six thesis domains remain in the model. Identity belongs to sign-in;
// the five service entries use language and tasks appropriate to the person.
const roleViews={
 '数字游民':{home:'乡野首页',title:'你的乡村生活',labels:['找工位','去乡游','换好物','约活动','邻里圈'],notes:['找个地方，安心工作','规划下一站乡野生活','闲置交换，技能互助','一起体验在地日常','遇见同频的人'],intro:'找工位、去乡游，开启自在的乡村生活。',icon:'leaf'},
 '当地村民':{home:'我的乡村',title:'我的在地服务',labels:['共享空间','介绍村庄','邻里互助','我的认养','乡邻日常'],notes:['分享家门口的工作空间','把家乡介绍给新朋友','交换资源，分享手艺','照料认养，记录生长','和新老邻居聊聊天'],intro:'分享在地资源，照料认养，与新邻居相遇。',icon:'home'},
 '企业':{home:'企业工作台',title:'企业合作',labels:['预约空间','探访乡村','资源合作','共创活动','招募人才'],notes:['为团队寻找工作空间','发现合适的合作村庄','发布资源，寻找伙伴','发起一场品牌共创','发布项目，查看申请'],intro:'发布合作项目，寻找人才，与乡村共同成长。',icon:'box'},
 '数字游民公社':{home:'公社工作台',title:'公社日常运营',labels:['工位运营','村庄展示','资源与报修','发起活动','公社日常'],notes:['发布工位，查看预约','更新村庄与出行信息','跟进共享资源与维修','组织活动，查看报名','连接社群，了解参与'],intro:'安排空间、组织活动，让社区的日常有序发生。',icon:'community'},
 '平台管理员':{home:'审核工作台',title:'待办与审核',labels:['工位审核','村庄审核','资源审核','活动审核','社区审核'],notes:['核对上架与预约信息','核验村庄资料','审核资源，跟进报修','审核活动与认养动态','审核合作与社区内容'],intro:'查看待办，核对资料，处理各板块的审核申请。',icon:'check'}
};
const domainKeys=['desk','map','box','calendar','community'];
const domainEnglish=['WORKSPACE','JOURNEY','SHARING','EXPERIENCES','COMMUNITY'];
const domainKinds={desk:['工位上架'],map:['村庄资料'],box:['资源发布'],calendar:['活动申请','认养动态'],community:['兼职项目']};
const originals={home,userPage,deskPage,travelPage,resourcePage,activityPage,communityPage,action,approvalForm};
const isReviewer=()=>state.profile.role==='平台管理员';
const isHost=()=>state.profile.role==='数字游民公社';
const currentView=()=>roleViews[state.profile.role]||roleViews['数字游民'];
function signedIn(){return state.loginVersion===2&&roles.includes(state.profile.role)}
function loginPage(){
 $('#app').innerHTML=`<main class="loginpage"><section class="loginintro"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div><b>乡约码上行</b><small>LIVE & WORK, NATURALLY</small></div></div><div class="loginmessage"><div class="eyebrow">DIFFERENT ROLES, ONE COMMUNITY</div><h1 class="serif">从你的身份出发，<br>与乡村发生连接。</h1><p>无论是远道而来的游民，还是熟悉这片土地的村民，<br>每一种参与，都让这里的生活更丰富。</p></div><div class="loginart">${landscape()}</div></section><section class="loginform"><div class="eyebrow">WELCOME TO XIANGYUE</div><h2>你好，欢迎来到乡约。</h2><p class="intro">选择你的身份，进入属于你的空间。</p><form id="login-form"><label class="field">怎么称呼你<input name="nickname" autocomplete="nickname" maxlength="20" value="${esc(state.profile.name)}" required placeholder="输入你的昵称"></label><fieldset class="identitychoices"><legend>我以什么身份加入</legend>${roles.map((r,i)=>`<label class="identitychoice"><input type="radio" name="identity" value="${r}" ${state.profile.role===r?'checked':''} required><span class="identityicon">${icon(roleViews[r].icon)}</span><span><b>${r}</b><small>${roleViews[r].intro}</small></span><span class="radiomark"></span></label>`).join('')}</fieldset><button class="btn login-submit" type="submit">以所选身份进入 ${icon('arrow')}</button><p class="help">当前为登录流程演示，无需真实账号或密码。</p></form></section></main>`;
 $('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('nickname').trim(),role=f.get('identity');if(!name)return toast('请填写你的昵称。');if(!roles.includes(role))return;state.profile.name=name;state.profile.role=role;state.loginVersion=2;save();page='home';tab='';location.hash='home';render();window.scrollTo(0,0)};
}
render=function(){
 if(!signedIn()){loginPage();return}
 const view=currentView();modules.splice(0,modules.length,...domainKeys.map((k,i)=>[k,view.labels[i],view.notes[i],domainEnglish[i]]));
 if(!['home','user',...domainKeys].includes(page))page='home';
 const meta=modules.find(m=>m[0]===page),title=page==='home'?view.home:page==='user'?'我的':meta[1];
 let body=({home,user:userPage,desk:deskPage,map:travelPage,box:resourcePage,calendar:activityPage,community:communityPage}[page])();
 body=body.replaceAll('用户管理','我的').replaceAll('社区管理','邻里圈').replaceAll('切换平台管理员演示角色','请使用审核身份登录').replaceAll('切换平台管理员可处理审核','待审核').replaceAll('五类用户','五类身份');
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div><b>乡约码上行</b><small>LIVE & WORK, NATURALLY</small></div></div><button class="navbutton ${page==='home'?'active':''}" data-go="home">${icon('home')}${view.home}</button><div class="navlabel">${view.title}</div>${modules.map(m=>`<button class="navbutton ${page===m[0]?'active':''}" data-go="${m[0]}">${icon(m[0])}${m[1]}</button>`).join('')}<div class="sidebottom"><div class="sidequote">${icon(view.icon)}${view.intro}</div><button class="profilemini ${page==='user'?'profileactive':''}" data-go="user"><span class="avatar">${esc(state.profile.name[0])}</span><span style="text-align:left"><b>${esc(state.profile.name)}</b><br><small>${state.profile.role} · 我的</small></span></button><button class="textbtn signout" data-action="signout">退出 / 切换登录身份 ${icon('arrow')}</button></div></aside><div class="main"><header class="topbar"><button class="mobilemenu" data-action="menu" aria-label="打开功能导航">${icon('menu')}</button><span class="mobilebrand">乡约码上行</span><div class="crumb">${view.home}<span> / </span>${title}</div><div class="topright"><span class="badge">${state.profile.role}</span><button data-action="notifications" aria-label="查看通知">${icon('bell')}</button><button class="avatar" data-go="user" aria-label="我的资料">${esc(state.profile.name[0])}</button></div></header><main class="content">${body}<footer class="footer"><span>乡约码上行 · 让每一种参与，都有归属</span><span>交互演示 · 操作记录保存在当前浏览器</span></footer></main></div>`;
 bind();
 // Identity is selected at sign-in, never as an ordinary service tab.
 const communityTabs=$('.tabs');if(page==='community'&&!isReviewer()&&!isHost()&&communityTabs){communityTabs.querySelectorAll('[data-tab="运营与审核"]').forEach(x=>x.remove())}
};
home=function(){
 if(state.profile.role==='数字游民')return originals.home().replace('六种连接，一种向往的生活','从工作到生活，找到你的乡野日常');
 const view=currentView(),pending=state.approvals.filter(a=>a.status==='待审核').length;
 return `${heading(`你好，${esc(state.profile.name)}。`,view.intro)}<section class="hero rolehero"><div class="heroart">${landscape()}</div><div class="herotext"><div class="herotag">${isReviewer()?'CARE FOR EVERY CONNECTION':'GROW TOGETHER, LIVE TOGETHER'}</div><h2 class="serif">${isReviewer()?'让每一份连接，<br>多一份安心。':state.profile.role==='企业'?'把新的可能，<br>带到乡村。':'在熟悉的乡野，<br>一起创造新日常。'}</h2><p>${view.intro}</p></div></section><div class="sectiontitle"><h2>${view.title}</h2><small>按你的身份，安排今天的事</small></div><div class="modules">${modules.map(m=>`<button class="module" data-go="${m[0]}"><span class="moduleicon">${icon(m[0])}</span><b>${m[1]}</b><small>${m[2]}</small></button>`).join('')}</div>${isReviewer()?`<div class="stats"><div class="stat"><small>待审核资料</small><b>${pending}</b><small>分板块处理</small></div><div class="stat"><small>待核验身份</small><b>${state.certs.filter(c=>c.status==='待审核').length}</b><button class="textbtn" data-action="identity-review">去核验身份 →</button></div><div class="stat"><small>待处理申请</small><b>${state.requests.filter(r=>r.status==='待处理').length}</b><small>报修、交换与合作</small></div><div class="stat"><small>本机社区动态</small><b>${state.posts.length}</b><button class="textbtn" data-go="community">查看内容 →</button></div></div>`:`<div class="sectiontitle"><h2>最近提交</h2><small>跟进每一次参与</small></div>${submittedPanel()}`}`;
};
function submittedPanel(kinds=null){const list=state.approvals.filter(a=>(!kinds||kinds.includes(a.kind))&&(!a.submitterRole||a.submitterRole===state.profile.role));return `<div class="panel">${list.length?list.slice().reverse().map(a=>`<div class="record"><div><h3>${esc(a.title)}</h3><small>${esc(a.kind)} · ${esc(a.desc)}</small></div><span class="tag">${a.status}</span></div>`).join(''):empty('还没有提交记录，新的发布会在这里显示进度。')}</div>`}
function reviewPanel(domain){const kinds=domain==='user'?['资格认证']:domainKinds[domain],list=state.approvals.filter(a=>kinds.includes(a.kind));return `<div class="panel"><div class="sectiontitle" style="margin-top:0"><h2>待核对的资料</h2><small>${list.filter(a=>a.status==='待审核').length} 条待审核</small></div>${list.length?list.slice().reverse().map(a=>`<div class="record"><div><h3>${esc(a.title)} <span class="tag">${esc(a.kind)}</span></h3><small>${esc(a.desc)}<br>${esc(a.submitterRole||'社区用户')} · ${esc(a.status)}</small></div>${a.status==='待审核'?`<div class="recordactions">${btn('通过','approve','tiny',`data-id="${a.id}" data-next="已通过"`)}${btn('驳回','approve','secondary tiny',`data-id="${a.id}" data-next="已驳回"`)}</div>`:''}</div>`).join(''):empty('目前没有待审核资料，新提交会自动出现在这里。')}</div>`}
function requestQueue(kinds){const list=state.requests.filter(r=>kinds.includes(r.kind));return `<div class="panel"><h3>服务申请</h3>${list.length?list.slice().reverse().map(r=>`<div class="record"><div><h3>${esc(r.target)} <span class="tag">${r.kind}</span></h3><small>${esc(r.note)}<br>${r.status}</small></div>${r.status==='待处理'?`<div class="recordactions">${btn('受理','service-handle','tiny',`data-id="${r.id}"`)}${btn('驳回','service-reject','secondary tiny',`data-id="${r.id}"`)}</div>`:''}</div>`).join(''):empty('暂时没有相关申请。')}</div>`}
function reviewPage(domain){const i=domainKeys.indexOf(domain);return `${heading(currentView().labels[i],currentView().notes[i])}${domain==='desk'?tabs(['待审资料','预约记录']):domain==='box'?tabs(['待审资源','服务申请']):domain==='community'?tabs(['合作审核','社区内容','合作申请','运营概览']):''}${domain==='desk'&&tab==='预约记录'?bookingOverview():domain==='box'&&tab==='服务申请'?requestQueue(['闲置交换','技能互助','设施报修']):domain==='community'&&tab==='社区内容'?`<div>${[...state.posts].reverse().concat(seedPosts).filter(p=>!state.hiddenPosts.includes(p.id)).map(postCard).join('')}</div>`:domain==='community'&&tab==='合作申请'?requestQueue(['兼职合作','同行邀请']):domain==='community'&&tab==='运营概览'?report():reviewPanel(domain)}`}
function bookingOverview(){return `<div class="panel">${state.bookings.length?state.bookings.slice().reverse().map(b=>`<div class="record"><div><h3>${esc(b.name)}</h3><small>${b.date} · ${b.time} · ${b.seat} 号</small></div><span class="tag">${b.status}</span></div>`).join(''):empty('暂无预约记录，游民预约后会出现在这里。')}</div>`}
deskPage=function(){
 if(isReviewer())return reviewPage('desk');
 if(isHost()||state.profile.role==='当地村民')return `${heading(currentView().labels[0],currentView().notes[0],btn('发布新空间','space-publish'))}${tabs(['空间展示','提交记录','预约记录'])}${tab==='提交记录'?submittedPanel(['工位上架']):tab==='预约记录'?bookingOverview():`<div class="grid">${spaces.map(s=>`<article class="card"><div class="art">${landscape('desk')}</div><div class="cardbody"><h3>${s.name}</h3><p>${s.place} · ${s.area}</p>${tags([s.net,...s.tags])}<div class="cardfoot"><span class="price">¥${s.price}<small> / 天</small></span><span class="tag">展示中</span></div></div></article>`).join('')}</div>`}`;
 return originals.deskPage();
};
travelPage=function(){if(isReviewer())return reviewPage('map');if(isHost()||state.profile.role==='当地村民')return `${heading(currentView().labels[1],currentView().notes[1],btn('提交村庄资料','village-publish'))}<div class="grid">${villages.map(v=>`<article class="card"><div class="art">${landscape()}</div><div class="cardbody"><h3>${v.name}</h3><p>${v.desc}</p>${tags([v.tag,'网络 '+v.net+' Mbps'])}</div></article>`).join('')}</div><div class="sectiontitle"><h2>资料提交进度</h2></div>${submittedPanel(['村庄资料'])}`;return originals.travelPage()};
resourcePage=function(){if(isReviewer())return reviewPage('box');if(isHost())return `${heading('资源与报修','跟进交换与技能需求，及时处理公共设施问题。')}${tabs(['服务申请','共享资源'])}${tab==='共享资源'?`<div class="grid">${resourceResults()}</div>`:requestQueue(['闲置交换','技能互助','设施报修'])}`;return originals.resourcePage()};
activityPage=function(){if(isReviewer())return reviewPage('calendar');if(state.profile.role==='当地村民')return `${heading('我的认养','照料每一份生长，与认养的朋友分享近况。',btn('更新生长动态','growth'))}${tabs(['生长记录','认养意向'])}${tab==='认养意向'?`<div class="panel">${state.adoptions.length?state.adoptions.map(id=>`<div class="record"><div><h3>${adoptionName(id)}</h3><small>已收到本机认养意向 · 未产生实际付款</small></div><span class="tag">待联系确认</span></div>`).join(''):empty('暂时还没有认养意向。')}</div>`:submittedPanel(['认养动态'])}`;
 if(isHost()||state.profile.role==='企业')return `${heading(currentView().labels[3],'提交活动方案，跟进审核和报名情况。',btn('发起新活动','propose-event'))}${tabs(['我发起的','报名记录','发现活动'])}${tab==='发现活动'?`<div class="grid">${activities.map(activityCard).join('')}</div>`:tab==='报名记录'?`<div class="panel">${state.events.length?state.events.map(id=>{const a=activities.find(a=>a.id===id);return a?`<div class="record"><div><h3>${esc(a.name)}</h3><small>${eventDate(a)} · ${esc(a.place)}</small></div><span class="tag">本机报名 1 人</span></div>`:''}).join(''):empty('暂无活动报名记录。')}</div>`:submittedPanel(['活动申请'])}`;return originals.activityPage()};
communityPage=function(){if(isReviewer())return reviewPage('community');if(state.profile.role==='企业')return `${heading('招募人才','让专业技能与乡村项目相遇。',btn('发布合作项目','publish-job'))}${tabs(['我的项目','合作申请'])}${tab==='合作申请'?requestQueue(['兼职合作']):submittedPanel(['兼职项目'])}`;if(!isHost()&&tab==='运营与审核')tab='邻里广场';return originals.communityPage()};
userPage=function(){return `${heading('我的','个人资料、身份认证与申请记录。',btn('退出 / 切换身份','signout','secondary'))}${tabs(isReviewer()?['个人资料','身份核验']:['个人资料','身份认证','我的申请'])}${isReviewer()&&tab==='身份核验'?reviewPanel('user'):tab==='身份认证'?`<div class="panel"><div class="profilecard"><span class="avatar">${icon(currentView().icon)}</span><div><h2>${state.profile.role}</h2><p>当前登录身份</p></div></div>${btn('提交身份认证','certify','secondary')}<h3 style="margin-top:24px">认证进度</h3>${state.certs.length?state.certs.map(c=>`<div class="record"><div><h3>${esc(c.org)}</h3><small>${c.role}</small></div><span class="tag">${c.status}</span></div>`).join(''):empty('尚未提交认证。')}</div>`:(()=>{const html=originals.userPage();return html.slice(html.indexOf('</div>',html.indexOf('class="tabs"'))+6)})()}`};
function submissionForm(kind){modal(kind,`<form id="role-submit"><label class="field">${kind==='工位上架'?'空间名称':kind==='村庄资料'?'村庄名称':'资源名称'}<input name="title" maxlength="60" required></label><label class="field">${kind==='工位上架'?'位置、设施、开放时段与参考价格':kind==='村庄资料'?'交通、网络、住宿与村庄介绍':'资源内容与交换方式'}<textarea name="desc" maxlength="1000" required></textarea></label><button class="btn">提交审核</button><p class="help">演示资料进入对应板块的审核队列。</p></form>`);$('#role-submit').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.approvals.push({id:uid(),kind,title:f.get('title'),desc:f.get('desc'),submitterRole:state.profile.role,status:'待审核'});save();close();render();toast('已提交审核，可查看处理进度。')}}
approvalForm=function(kind){originals.approvalForm(kind);const form=$('#approval-form'),submit=form.onsubmit;form.onsubmit=e=>{const previous=new Set(state.approvals.map(a=>a.id));submit(e);state.approvals.filter(a=>!previous.has(a.id)).forEach(a=>a.submitterRole=state.profile.role);save()};const help=form.querySelector('.help');if(help)help.textContent='提交后等待平台审核，处理结果会显示在你的提交记录中。'};
action=function(a,d){
 if(a==='signout'){state.loginVersion=0;save();close();page='home';tab='';location.hash='login';loginPage();window.scrollTo(0,0);return}
 if(a==='role')return;
 if(a==='identity-review'){go('user','身份核验');return}
 if(a==='space-publish'){submissionForm('工位上架');return}
 if(a==='village-publish'){submissionForm('村庄资料');return}
 if(a==='service-handle'||a==='service-reject'){if(!isReviewer()&&!isHost()&&state.profile.role!=='企业')return;const r=state.requests.find(r=>r.id===d.id);if(!r)return;r.status=a==='service-handle'?'已受理':'已驳回';save();render();toast('申请处理结果已保存。');return}
 if(a==='publish-resource'){
  originals.action(a,d);const form=$('#resource-form'),submit=form.onsubmit;form.onsubmit=e=>{const prev=new Set(state.listings.map(i=>i.id));submit(e);state.listings.filter(i=>!prev.has(i.id)).forEach(i=>state.approvals.push({id:uid(),kind:'资源发布',title:i.name,desc:i.desc,listingId:i.id,submitterRole:state.profile.role,status:'待审核'}));save();render();toast('资源已提交，等待审核后公开展示。')};return
 }
 if(a==='approve'){const review=state.approvals.find(x=>x.id===d.id);if(!isReviewer())return;originals.action(a,d);if(review?.kind==='资源发布'){save();render()}return}
 originals.action(a,d);
};
// Pending resources remain visible to the submitter, but not in the marketplace.
const originalResourceResults=resourceResults;
resourceResults=function(){const pending=state.approvals.filter(a=>a.kind==='资源发布'&&a.status!=='已通过').map(a=>a.listingId),all=state.listings;if(tab!=='我的发布')state.listings=all.filter(i=>!pending.includes(i.id));const html=originalResourceResults();state.listings=all;return html};

